MODE = {'fwd': False}

def control(obs):
    st = obs.get('status')
    h = obs.get('hitch_deg', 0.0)
    t = obs.get('t', 0.0)
    if st in ('JACKKNIFED', 'PINNED') or abs(h) > 60:
        MODE['fwd'] = True
    if MODE['fwd'] and abs(h) < 15:
        MODE['fwd'] = False
    if MODE['fwd']:
        return (0.0, 1.0, 0.0)
    h_des = -4.0 if t < 10 else 0.0
    steer = 2.0 * (h - h_des)
    steer = max(-30.0, min(30.0, steer))
    return (steer, -1.0, -23.0)

