PH = {'mode': 'fwd', 't0': None}

def control(obs):
    t = obs.get('t', 0.0)
    h = obs.get('hitch_deg', 0.0)
    st = obs.get('status')
    if PH['t0'] is None:
        PH['t0'] = t
    if PH['mode'] == 'fwd':
        if t - PH['t0'] >= 2.0:
            PH['mode'] = 'rev'
            PH['t0'] = t
        else:
            return (0.0, 0.2, 0.0)
    if st in ('PINNED', 'JACKKNIFED'):
        PH['mode'] = 'fwd'
        PH['t0'] = t
        return (0.0, 0.0, -23.0)
    steer = 3.0 * (h + 8.0)
    steer = max(-30.0, min(30.0, steer))
    return (steer, -0.4, -23.0)

